(window.ArduinoSketches=window.ArduinoSketches||{})["b5_03_blocking_problem"]={"ok":true,"flash":1336,"ram":9,"program":"","name":"b5_03_blocking_problem","source":"// ==================================================================\n//   BAND 5, PART 6  -  THIS ONE FAILS ON PURPOSE\n//\n//   WHAT IT SHOULD DO\n//     A lamp fades slowly up and down, and a second light comes on\n//     whenever you hold a button.\n//\n//   WHAT IT ACTUALLY DOES\n//     The fade works perfectly. The button almost never does.\n//\n//   WHY\n//     Count the delays. 128 rounds at 20 ms each is about two and a\n//     half seconds of doing nothing at all. The button is checked\n//     ONCE, at the very bottom, after all of that.\n//\n//     Your press has to land in exactly that instant to be seen.\n//\n//     The board is not broken. It is busy. Every delay you have\n//     ever written stops the WHOLE board, not just one light.\n//\n//   WIRING\n//     Keep the Band 5 build exactly as it is and MOVE FOUR WIRES.\n//     Unplug the USB cable first.\n//\n//     DO THEM IN THIS ORDER. Only ONE wire fits in an Arduino pin,\n//     and pins 9 and 8 are both occupied right now.\n//\n//       1. the wire from j24 : pin 9  ->  OUT   (frees pin 9)\n//       2. the wire from j19 : pin 8  ->  PIN 6 (frees pin 8;\n//                                               this is the button)\n//       3. the wire from b1  : pin 2  ->  PIN 9 (the fading lamp)\n//       4. the wire from b5  : pin 3  ->  PIN 8 (the answer light)\n//\n//     Pin 9 matters. Only a pin with a ~ can fade, and pin 2,\n//     where that light was, cannot.\n//\n//     Lights 3 and 4 and buttons 3 and 4 are not used here, so\n//     leave them alone. Button 2 is not used either, but its wire\n//     had to come out of pin 9 to make room for the lamp.\n//\n//     WHEN YOU HAVE FINISHED PART 7, PUT ALL FOUR WIRES BACK:\n//       b1 -> pin 2, b5 -> pin 3, j19 -> pin 8, j24 -> pin 9,\n//     or the game in Part 9 will not work.\n// ==================================================================\n\nint buttonPin = 6;\nint lampPin = 9;\nint answerPin = 8;\n\nvoid setup() {\n  pinMode(buttonPin, INPUT_PULLUP);\n  pinMode(lampPin, OUTPUT);\n  pinMode(answerPin, OUTPUT);\n}\n\nvoid loop() {\n\n  for (int level = 0; level <= 255; level = level + 4) {\n    analogWrite(lampPin, level);\n    delay(20);\n  }\n  for (int level = 255; level >= 0; level = level - 4) {\n    analogWrite(lampPin, level);\n    delay(20);\n  }\n\n  if (digitalRead(buttonPin) == LOW) {\n    digitalWrite(answerPin, HIGH);\n  } else {\n    digitalWrite(answerPin, LOW);\n  }\n}\n","compiler":"arduino-cli 1.5.1, arduino:avr:uno"};
